        private static string _cachedQrSvg = null;

        public static string GetBuiltInSvg(string nameOrPath)
        {
            if (string.IsNullOrEmpty(nameOrPath)) return null;
            string key = Path.GetFileName(nameOrPath).ToLowerInvariant();

            if (key == "admin.svg") return AdminSvg;
            if (key == "dark-mode.svg") return DarkModeSvg;
            if (key == "light-mode.svg") return LightModeSvg;
            if (key == "logo-max.svg" || key == "logo.svg") return LogoMaxSvg;
            if (key == "qr_vietcombank.svg")
            {
                if (_cachedQrSvg == null)
                {
                    _cachedQrSvg = DecompressQrSvg();
                }
                return _cachedQrSvg;
            }
            return null;
        }

        private static string DecompressQrSvg()
        {
            try
            {
                string[] chunks = new string[]
                {
                    "",
                    "",
                    "",
                    "",
                    ""
                };
                string b64 = string.Concat(chunks);
                byte[] compressed = Convert.FromBase64String(b64);
                using (MemoryStream ms = new MemoryStream(compressed))
                using (GZipStream gz = new GZipStream(ms, CompressionMode.Decompress))
                using (MemoryStream outMs = new MemoryStream())
                {
                    byte[] buffer = new byte[8192];
                    int read;
                    while ((read = gz.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        outMs.Write(buffer, 0, read);
                    }
                    return Encoding.UTF8.GetString(outMs.ToArray());
                }
            }
            catch
            {
                return null;
            }
        }
